import com.gymie.workout.core.domain.workout.WorkoutStatus
import com.gymie.workout.core.domain.workout.specification.FinishReadinessView
import com.gymie.workout.core.domain.workout.specification.PreviousPerformance
import com.gymie.workout.core.domain.workout.specification.WorkoutDetail
import com.gymie.workout.core.exceptions.WorkoutNotFoundException
import com.gymie.workout.core.exceptions.WorkoutStaleException
import com.gymie.workout.core.services.workout.WorkoutFieldPatchService
import com.gymie.workout.core.services.workout.WorkoutFinishReadinessService
import com.gymie.workout.core.services.workout.WorkoutService
import com.gymie.workout.infrastructure.presentation.web.WorkoutExceptionHandler
import com.gymie.workout.infrastructure.presentation.web.WorkoutResponseAssembler
import io.mockk.clearMocks
import io.mockk.every
import io.mockk.mockk
import io.mockk.verify
import org.junit.jupiter.api.BeforeEach
import org.junit.jupiter.api.Test
import org.springframework.beans.factory.annotation.Autowired
import org.springframework.boot.test.context.TestConfiguration
import org.springframework.boot.webmvc.test.autoconfigure.WebMvcTest
import org.springframework.context.annotation.Bean
import org.springframework.context.annotation.Import
import org.springframework.http.HttpHeaders
import org.springframework.http.MediaType
import org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.csrf
import org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.user
import org.springframework.test.web.servlet.MockMvc
import org.springframework.test.web.servlet.get
import org.springframework.test.web.servlet.patch
import org.springframework.test.web.servlet.post
import org.springframework.test.web.servlet.put
import java.time.Instant
import java.time.LocalDate
import java.util.UUID

@WebMvcTest(controllers = [GroupSessionWorkoutController::class])
@Import(
    GroupSessionWorkoutController::class,
    GroupSessionExceptionHandler::class,
    WorkoutExceptionHandler::class,
    GroupSessionWorkoutControllerTest.TestConfig::class,
)
class GroupSessionWorkoutControllerTest {
    @Autowired lateinit var mockMvc: MockMvc

    @Autowired lateinit var objectMapper: ObjectMapper

    @Autowired lateinit var groupSessionQueryService: GroupSessionQueryService

    @Autowired lateinit var workoutService: WorkoutService

    @Autowired lateinit var workoutFieldPatchService: WorkoutFieldPatchService

    @Autowired lateinit var workoutFinishReadinessService: WorkoutFinishReadinessService

    @Autowired lateinit var responses: WorkoutResponseAssembler

    private val owner = UUID.fromString("11111111-1111-1111-1111-111111111111")
    private val jana = UUID.fromString("22222222-2222-2222-2222-222222222222")
    private val sessionId = UUID.randomUUID()
    private val workoutId = UUID.randomUUID()
    private val date = LocalDate.of(2026, 9, 4)

    @BeforeEach
    fun resetMocks() {
        clearMocks(groupSessionQueryService, workoutService, workoutFieldPatchService, workoutFinishReadinessService, responses)
    }

    private fun basePath() = "/api/group-sessions/$sessionId/participants/$jana/workout"

    private val stubWorkout =
        Workout(
            id = workoutId,
            userId = jana,
            scheduledDate = date,
            scheduledTime = null,
            unit = WeightUnit.KG,
            lifecycle = WorkoutLifecycle(status = WorkoutStatus.PLANNED),
        )

    private fun workout(): Workout = stubWorkout

    private fun workoutWithUpdatedAt(updatedAt: Instant): Workout =
        stubWorkout.copy(audit = stubWorkout.audit.copy(updatedAt = updatedAt, structureUpdatedAt = updatedAt))

    private fun workoutResponse() =
        com.gymie.workout.infrastructure.presentation.web.dto.WorkoutResponse(
            id = workoutId,
            scheduledDate = date,
            scheduledTime = null,
            unit = WeightUnit.KG,
            name = null,
            displayName = "Stub",
            notes = null,
            status = WorkoutStatus.PLANNED,
            startedAt = null,
            finishedAt = null,
            blocks = emptyList(),
        )

    @Test
    fun `get answers the participant's workout`() {
        every { groupSessionQueryService.participantWorkoutId(owner, sessionId, jana) } returns workoutId
        every { workoutService.getDetail(jana, workoutId) } returns WorkoutDetail(workout(), PreviousPerformance())
        every { responses.respond(workout(), PreviousPerformance()) } returns workoutResponse()

        mockMvc
            .get(basePath()) {
                with(user(owner.toString()))
            }.andExpect {
                status { isOk() }
                jsonPath("$.id") { value(workoutId.toString()) }
            }

        verify { workoutService.getDetail(jana, workoutId) }
    }

    @Test
    fun `put updates the participant's workout as that user`() {
        every { groupSessionQueryService.participantWorkoutIdForWrite(owner, sessionId, jana) } returns workoutId
        every {
            workoutService.update(
                userId = jana,
                id = workoutId,
                scheduledDate = date,
                scheduledTime = null,
                description = any(),
                blocks = any(),
                status = null,
            )
        } returns workout()
        every { responses.respond(workout()) } returns workoutResponse()

        mockMvc
            .put(basePath()) {
                with(user(owner.toString()))
                with(csrf())
                contentType = MediaType.APPLICATION_JSON
                content = objectMapper.writeValueAsString(mapOf("scheduledDate" to date.toString(), "blocks" to emptyList<Any>()))
            }.andExpect { status { isOk() } }

        verify {
            workoutService.update(
                userId = jana,
                id = workoutId,
                scheduledDate = date,
                scheduledTime = null,
                description = any(),
                blocks = any(),
                status = null,
            )
        }
    }

    @Test
    fun `patch notes updates as that user`() {
        every { groupSessionQueryService.participantWorkoutIdForWrite(owner, sessionId, jana) } returns workoutId
        every { workoutFieldPatchService.patchNotesAndScheduledTime(jana, workoutId, "hi", null, false) } returns workout()
        every { responses.respond(workout()) } returns workoutResponse()

        mockMvc
            .patch(basePath()) {
                with(user(owner.toString()))
                with(csrf())
                contentType = MediaType.APPLICATION_JSON
                content = """{"notes":"hi"}"""
            }.andExpect { status { isOk() } }

        verify { workoutFieldPatchService.patchNotesAndScheduledTime(jana, workoutId, "hi", null, false) }
    }

    @Test
    fun `patch block delegates with the resolved workout id`() {
        val blockId = UUID.randomUUID()
        every { groupSessionQueryService.participantWorkoutIdForWrite(owner, sessionId, jana) } returns workoutId
        every { workoutFieldPatchService.patchBlock(jana, workoutId, blockId, true, false) } returns workout()
        every { responses.respond(workout()) } returns workoutResponse()

        mockMvc
            .patch("${basePath()}/blocks/$blockId") {
                with(user(owner.toString()))
                with(csrf())
                contentType = MediaType.APPLICATION_JSON
                content = """{"collapsed":true,"completed":false}"""
            }.andExpect { status { isOk() } }

        verify { workoutFieldPatchService.patchBlock(jana, workoutId, blockId, true, false) }
    }

    @Test
    fun `patch exercise delegates with the resolved workout id`() {
        val exerciseId = UUID.randomUUID()
        every { groupSessionQueryService.participantWorkoutIdForWrite(owner, sessionId, jana) } returns workoutId
        every {
            workoutFieldPatchService.patchExercise(jana, workoutId, exerciseId, "note", ExerciseEvaluation.KEEP, null)
        } returns workout()
        every { responses.respond(workout()) } returns workoutResponse()

        mockMvc
            .patch("${basePath()}/exercises/$exerciseId") {
                with(user(owner.toString()))
                with(csrf())
                contentType = MediaType.APPLICATION_JSON
                content = """{"note":"note","evaluation":"KEEP","evaluationNote":null}"""
            }.andExpect { status { isOk() } }

        verify { workoutFieldPatchService.patchExercise(jana, workoutId, exerciseId, "note", ExerciseEvaluation.KEEP, null) }
    }

    @Test
    fun `patch set delegates with the resolved workout id`() {
        val setId = UUID.randomUUID()
        every { groupSessionQueryService.participantWorkoutIdForWrite(owner, sessionId, jana) } returns workoutId
        every {
            workoutFieldPatchService.patchSet(jana, workoutId, setId, null, null, true)
        } returns workout()
        every { responses.respond(workout()) } returns workoutResponse()

        mockMvc
            .patch("${basePath()}/sets/$setId") {
                with(user(owner.toString()))
                with(csrf())
                contentType = MediaType.APPLICATION_JSON
                content = """{"weight":null,"effort":null,"confirmed":true}"""
            }.andExpect { status { isOk() } }

        verify { workoutFieldPatchService.patchSet(jana, workoutId, setId, null, null, true) }
    }

    @Test
    fun `finish finishes the participant's workout`() {
        every { groupSessionQueryService.participantWorkoutIdForWrite(owner, sessionId, jana) } returns workoutId
        every { workoutService.finish(jana, workoutId) } returns workout()
        every { responses.respond(workout()) } returns workoutResponse()

        mockMvc
            .post("${basePath()}/finish") {
                with(user(owner.toString()))
                with(csrf())
            }.andExpect { status { isOk() } }

        verify { workoutService.finish(jana, workoutId) }
    }

    @Test
    fun `finish-readiness answers the participant's readiness`() {
        every { groupSessionQueryService.participantWorkoutId(owner, sessionId, jana) } returns workoutId
        every { workoutFinishReadinessService.finishReadiness(jana, workoutId) } returns
            FinishReadinessView(ready = true, issues = emptyList())

        mockMvc
            .get("${basePath()}/finish-readiness") {
                with(user(owner.toString()))
            }.andExpect {
                status { isOk() }
                jsonPath("$.ready") { value(true) }
            }

        verify { workoutFinishReadinessService.finishReadiness(jana, workoutId) }
    }

    @Test
    fun `a VIEW viewer reads the participant's workout`() {
        every { groupSessionQueryService.participantWorkoutId(owner, sessionId, jana) } returns workoutId
        every { workoutService.getDetail(jana, workoutId) } returns WorkoutDetail(workout(), PreviousPerformance())
        every { responses.respond(workout(), PreviousPerformance()) } returns workoutResponse()

        mockMvc
            .get(basePath()) {
                with(user(owner.toString()))
            }.andExpect { status { isOk() } }
    }

    @Test
    fun `a VIEW viewer is refused 403 edit_access_required on a write`() {
        val setId = UUID.randomUUID()
        every {
            groupSessionQueryService.participantWorkoutIdForWrite(owner, sessionId, jana)
        } throws GroupSessionForbiddenException.editAccessRequired(sessionId)

        mockMvc
            .patch("${basePath()}/sets/$setId") {
                with(user(owner.toString()))
                with(csrf())
                contentType = MediaType.APPLICATION_JSON
                content = """{"weight":null,"effort":null,"confirmed":true}"""
            }.andExpect {
                status { isForbidden() }
                jsonPath("$.code") { value("edit_access_required") }
            }

        verify(exactly = 0) { workoutFieldPatchService.patchSet(any(), any(), any(), any(), any(), any()) }
    }

    @Test
    fun `a non-participant is refused with 404`() {
        every {
            groupSessionQueryService.participantWorkoutId(owner, sessionId, jana)
        } throws GroupSessionNotFoundException(sessionId, jana)

        mockMvc
            .get(basePath()) {
                with(user(owner.toString()))
            }.andExpect { status { isNotFound() } }
    }

    @Test
    fun `a workout not-found from the workout module answers 404`() {
        every { groupSessionQueryService.participantWorkoutId(owner, sessionId, jana) } returns workoutId
        every { workoutService.getDetail(jana, workoutId) } throws WorkoutNotFoundException(workoutId)

        mockMvc
            .get(basePath()) {
                with(user(owner.toString()))
            }.andExpect { status { isNotFound() } }
    }

    @Test
    fun `GET participant workout echoes ETag and resolves through the read path`() {
        val updatedAt = Instant.parse("2026-09-04T09:00:00.123456Z")
        every { groupSessionQueryService.participantWorkoutId(owner, sessionId, jana) } returns workoutId
        every { workoutService.getDetail(jana, workoutId) } returns WorkoutDetail(workoutWithUpdatedAt(updatedAt), PreviousPerformance())
        every { responses.respond(workoutWithUpdatedAt(updatedAt), PreviousPerformance()) } returns workoutResponse()

        mockMvc
            .get(basePath()) {
                with(user(owner.toString()))
            }.andExpect {
                status { isOk() }
                header { string(HttpHeaders.ETAG, "\"$updatedAt\"") }
            }

        verify { groupSessionQueryService.participantWorkoutId(owner, sessionId, jana) }
        verify(exactly = 0) { groupSessionQueryService.participantWorkoutIdForWrite(any(), any(), any()) }
    }

    @Test
    fun `PUT participant workout passes If-Match through and echoes the new ETag`() {
        val ifMatch = Instant.parse("2026-09-04T09:00:00.123456Z")
        val newUpdatedAt = Instant.parse("2026-09-04T09:05:00.654321Z")
        every { groupSessionQueryService.participantWorkoutIdForWrite(owner, sessionId, jana) } returns workoutId
        every {
            workoutService.update(
                userId = jana,
                id = workoutId,
                scheduledDate = date,
                scheduledTime = null,
                description = any(),
                blocks = any(),
                status = null,
                expectedUpdatedAt = ifMatch,
            )
        } returns workoutWithUpdatedAt(newUpdatedAt)
        every { responses.respond(workoutWithUpdatedAt(newUpdatedAt)) } returns workoutResponse()

        mockMvc
            .put(basePath()) {
                with(user(owner.toString()))
                with(csrf())
                headers { set(HttpHeaders.IF_MATCH, "\"$ifMatch\"") }
                contentType = MediaType.APPLICATION_JSON
                content = objectMapper.writeValueAsString(mapOf("scheduledDate" to date.toString(), "blocks" to emptyList<Any>()))
            }.andExpect {
                status { isOk() }
                header { string(HttpHeaders.ETAG, "\"$newUpdatedAt\"") }
            }

        verify {
            workoutService.update(
                userId = jana,
                id = workoutId,
                scheduledDate = date,
                scheduledTime = null,
                description = any(),
                blocks = any(),
                status = null,
                expectedUpdatedAt = ifMatch,
            )
        }
    }

    @Test
    fun `the participant's etag is the structure version, not updatedAt`() {
        val structureVersion = Instant.parse("2026-09-04T09:00:00.123456Z")
        val loggedSince = Instant.parse("2026-09-04T09:30:00.654321Z")
        val logged = stubWorkout.copy(audit = stubWorkout.audit.copy(updatedAt = loggedSince, structureUpdatedAt = structureVersion))
        every { groupSessionQueryService.participantWorkoutId(owner, sessionId, jana) } returns workoutId
        every { groupSessionQueryService.participantWorkoutIdForWrite(owner, sessionId, jana) } returns workoutId
        every { workoutService.getDetail(jana, workoutId) } returns WorkoutDetail(logged, PreviousPerformance())
        every { responses.respond(logged, PreviousPerformance()) } returns workoutResponse()
        every {
            workoutService.update(
                userId = jana,
                id = workoutId,
                scheduledDate = date,
                scheduledTime = null,
                description = any(),
                blocks = any(),
                status = null,
                expectedUpdatedAt = structureVersion,
            )
        } returns logged
        every { responses.respond(logged) } returns workoutResponse()

        mockMvc
            .get(basePath()) {
                with(user(owner.toString()))
            }.andExpect {
                status { isOk() }
                header { string(HttpHeaders.ETAG, "\"$structureVersion\"") }
            }
        mockMvc
            .put(basePath()) {
                with(user(owner.toString()))
                with(csrf())
                headers { set(HttpHeaders.IF_MATCH, "\"$structureVersion\"") }
                contentType = MediaType.APPLICATION_JSON
                content = objectMapper.writeValueAsString(mapOf("scheduledDate" to date.toString(), "blocks" to emptyList<Any>()))
            }.andExpect {
                status { isOk() }
                header { string(HttpHeaders.ETAG, "\"$structureVersion\"") }
            }
    }

    @Test
    fun `PUT participant workout with a stale token answers 409 carrying the current etag`() {
        val currentUpdatedAt = Instant.parse("2026-09-04T09:05:00.654321Z")
        every { groupSessionQueryService.participantWorkoutIdForWrite(owner, sessionId, jana) } returns workoutId
        every {
            workoutService.update(
                userId = jana,
                id = workoutId,
                scheduledDate = date,
                scheduledTime = null,
                description = any(),
                blocks = any(),
                status = null,
                expectedUpdatedAt = any(),
            )
        } throws WorkoutStaleException(workoutId, currentUpdatedAt)

        mockMvc
            .put(basePath()) {
                with(user(owner.toString()))
                with(csrf())
                headers { set(HttpHeaders.IF_MATCH, "\"2026-01-01T00:00:00Z\"") }
                contentType = MediaType.APPLICATION_JSON
                content = objectMapper.writeValueAsString(mapOf("scheduledDate" to date.toString(), "blocks" to emptyList<Any>()))
            }.andExpect {
                status { isEqualTo(409) }
                jsonPath("$.etag") { value("\"$currentUpdatedAt\"") }
            }
    }

    @Test
    fun `every write route resolves through participantWorkoutIdForWrite and answers 403 when revoked`() {
        val blockId = UUID.randomUUID()
        val exerciseId = UUID.randomUUID()
        val setId = UUID.randomUUID()
        every {
            groupSessionQueryService.participantWorkoutIdForWrite(owner, sessionId, jana)
        } throws GroupSessionForbiddenException.writeAccessRevoked(sessionId, jana)

        mockMvc
            .put(basePath()) {
                with(user(owner.toString()))
                with(csrf())
                contentType = MediaType.APPLICATION_JSON
                content = objectMapper.writeValueAsString(mapOf("scheduledDate" to date.toString(), "blocks" to emptyList<Any>()))
            }.andExpect { status { isForbidden() } }

        mockMvc
            .patch(basePath()) {
                with(user(owner.toString()))
                with(csrf())
                contentType = MediaType.APPLICATION_JSON
                content = """{"notes":"hi"}"""
            }.andExpect { status { isForbidden() } }

        mockMvc
            .patch("${basePath()}/blocks/$blockId") {
                with(user(owner.toString()))
                with(csrf())
                contentType = MediaType.APPLICATION_JSON
                content = """{"collapsed":true,"completed":false}"""
            }.andExpect { status { isForbidden() } }

        mockMvc
            .patch("${basePath()}/exercises/$exerciseId") {
                with(user(owner.toString()))
                with(csrf())
                contentType = MediaType.APPLICATION_JSON
                content = """{"note":"note","evaluation":"KEEP","evaluationNote":null}"""
            }.andExpect { status { isForbidden() } }

        mockMvc
            .patch("${basePath()}/sets/$setId") {
                with(user(owner.toString()))
                with(csrf())
                contentType = MediaType.APPLICATION_JSON
                content = """{"weight":null,"effort":null,"confirmed":true}"""
            }.andExpect { status { isForbidden() } }

        mockMvc
            .post("${basePath()}/finish") {
                with(user(owner.toString()))
                with(csrf())
            }.andExpect { status { isForbidden() } }

        verify(exactly = 0) { groupSessionQueryService.participantWorkoutId(any(), any(), any()) }
    }

    @TestConfiguration
    class TestConfig {
        @Bean
        fun groupSessionQueryService(): GroupSessionQueryService = mockk()

        @Bean
        fun workoutService(): WorkoutService = mockk()

        @Bean
        fun workoutFieldPatchService(): WorkoutFieldPatchService = mockk()

        @Bean
        fun workoutFinishReadinessService(): WorkoutFinishReadinessService = mockk()

        @Bean
        fun workoutResponseAssembler(): WorkoutResponseAssembler = mockk()
    }
}

