 * The wire shape of [com.gymie.workout.core.domain.workout.SetWeight]:
 * `{"kind":"MEASURED","value":60.0}` for a numeric weight, `{"kind":"BW"}` for bodyweight, and
 * `null` (the whole field absent or `null`) for a weight not filled in.
 *
 * A `MEASURED` weight carries a `value` and **no unit**: the unit is [WorkoutResponse.unit], stated
 * once for the whole workout. `BW` carries no value either — the body is not measured in anything —
 * and the `NON_NULL` inclusion below is what keeps `{"kind":"BW"}` free of the key.
 */
data class SetWeightDto(
    val kind: String,
    @field:JsonInclude(JsonInclude.Include.NON_NULL)
    val value: BigDecimal? = null,
) {
    companion object {
        const val KIND_MEASURED = "MEASURED"
        const val KIND_BODYWEIGHT = "BW"
    }
}

/**
 * The wire shape of [com.gymie.workout.core.domain.workout.SetEffort], mirroring [SetWeightDto]:
 * `{"kind":"COUNT","value":10}` for a recorded number, `{"kind":"MAX"}` for "as many as possible",
 * and `null` for effort not filled in.
 *
 * `MAX` is a *prescription*, and the whole reason the tagged shape exists: a bare integer could
 * only ever say "unset" or a number, which would report a stored `MAX` as `null` and lose the one
 * distinction this contract is here to carry.
 */
data class SetEffortDto(
    val kind: String,
    @field:JsonInclude(JsonInclude.Include.NON_NULL)
    val value: Int? = null,
) {
    companion object {
        const val KIND_MAX = "MAX"
        const val KIND_COUNT = "COUNT"
    }
}

