/** The floor set PATCH's compare-and-set wire contract (KAN-757, decision `value-compare-and-set`). */
@WebMvcTest(controllers = [GroupSessionWorkoutController::class])
@Import(
    GroupSessionWorkoutController::class,
    GroupSessionExceptionHandler::class,
    WorkoutExceptionHandler::class,
    GroupSessionFloorSetConflictTest.TestConfig::class,
)
class GroupSessionFloorSetConflictTest {
    @Autowired lateinit var mockMvc: MockMvc

    @Autowired lateinit var groupSessionQueryService: GroupSessionQueryService

    @Autowired lateinit var workoutFieldPatchService: WorkoutFieldPatchService

    private val owner = UUID.fromString("11111111-1111-1111-1111-111111111111")
    private val jana = UUID.fromString("22222222-2222-2222-2222-222222222222")
    private val sessionId = UUID.randomUUID()
    private val workoutId = UUID.randomUUID()
    private val setId = UUID.randomUUID()
    private val changedAt = Instant.parse("2026-10-07T10:00:00Z")

    @BeforeEach
    fun resetMocks() {
        clearMocks(groupSessionQueryService, workoutFieldPatchService)
        every { groupSessionQueryService.participantWorkoutIdForWrite(owner, sessionId, jana) } returns workoutId
    }

    private fun path() = "/api/group-sessions/$sessionId/participants/$jana/workout/sets/$setId"

    private fun patch(body: String) =
        mockMvc.patch(path()) {
            with(user(owner.toString()))
            with(csrf())
            contentType = MediaType.APPLICATION_JSON
            content = body
        }

    @Test
    fun `an expected block is converted and the caller is the actor`() {
        every {
            workoutFieldPatchService.patchSet(
                jana,
                workoutId,
                setId,
                SetWeight.Measured(BigDecimal("65")),
                SetEffort.Count(8),
                true,
                owner,
                SetValues(SetWeight.Measured(BigDecimal("60")), SetEffort.Count(10), confirmed = false),
            )
        } returns
            com.gymie.workout.core.domain.workout
                .Workout(
                    id = workoutId,
                    userId = jana,
                    scheduledDate = LocalDate.of(2026, 9, 4),
                    scheduledTime = null,
                    unit = com.gymie.workout.core.domain.workout.WeightUnit.KG,
                    lifecycle =
                        com.gymie.workout.core.domain.workout
                            .WorkoutLifecycle(status = com.gymie.workout.core.domain.workout.WorkoutStatus.PLANNED),
                )
        every { workoutFieldPatchService.patchSet(any(), any(), any(), any(), any(), any(), any(), any()) } returns
            com.gymie.workout.core.domain.workout
                .Workout(
                    id = workoutId,
                    userId = jana,
                    scheduledDate = LocalDate.of(2026, 9, 4),
                    scheduledTime = null,
                    unit = com.gymie.workout.core.domain.workout.WeightUnit.KG,
                    lifecycle =
                        com.gymie.workout.core.domain.workout
                            .WorkoutLifecycle(status = com.gymie.workout.core.domain.workout.WorkoutStatus.PLANNED),
                )

        patch(
            """{"weight":{"kind":"MEASURED","value":65},"effort":{"kind":"COUNT","value":8},"confirmed":true,
                "expected":{"weight":{"kind":"MEASURED","value":60},"effort":{"kind":"COUNT","value":10},"confirmed":false}}""",
        ).andExpect { status { isOk() } }

        verify {
            workoutFieldPatchService.patchSet(
                jana,
                workoutId,
                setId,
                SetWeight.Measured(BigDecimal("65")),
                SetEffort.Count(8),
                true,
                owner,
                SetValues(SetWeight.Measured(BigDecimal("60")), SetEffort.Count(10), confirmed = false),
            )
        }
    }

    @Test
    fun `a stale expected answers set_changed with the current values and who changed them`() {
        every { groupSessionQueryService.profileOf(jana) } returns ParticipantProfile(jana, "Jana Horvat", "jana", null, null)
        every { workoutFieldPatchService.patchSet(any(), any(), any(), any(), any(), any(), any(), any()) } throws
            WorkoutSetChangedException(
                WorkoutSet(
                    id = setId,
                    position = 0,
                    weight = SetWeight.Measured(BigDecimal("65")),
                    effort = SetEffort.Count(8),
                    confirmedAt = changedAt,
                    updatedAt = changedAt,
                    updatedBy = jana,
                ),
            )

        patch(
            """{"weight":{"kind":"MEASURED","value":60},"effort":{"kind":"COUNT","value":10},"confirmed":false,
                "expected":{"weight":{"kind":"MEASURED","value":60},"effort":{"kind":"COUNT","value":10},"confirmed":false}}""",
        ).andExpect {
            status { isConflict() }
            jsonPath("$.detail") { value("This set was changed on another phone.") }
            jsonPath("$.code") { value("set_changed") }
            jsonPath("$.current.weight.kind") { value("MEASURED") }
            jsonPath("$.current.weight.value") { value(65) }
            jsonPath("$.current.effort.kind") { value("COUNT") }
            jsonPath("$.current.effort.value") { value(8) }
            jsonPath("$.current.confirmed") { value(true) }
            jsonPath("$.updatedBy.id") { value(jana.toString()) }
            jsonPath("$.updatedBy.displayName") { value("Jana Horvat") }
            jsonPath("$.updatedAt") { value("2026-10-07T10:00:00Z") }
        }
    }

    @Test
    fun `a set no patch has stamped carries no author or time`() {
        every { workoutFieldPatchService.patchSet(any(), any(), any(), any(), any(), any(), any(), any()) } throws
            WorkoutSetChangedException(
                WorkoutSet(id = setId, position = 0, weight = SetWeight.Measured(BigDecimal("65")), effort = SetEffort.Count(8)),
            )

        patch(
            """{"weight":null,"effort":null,"confirmed":false,
                "expected":{"weight":null,"effort":null,"confirmed":false}}""",
        ).andExpect {
            status { isConflict() }
            jsonPath("$.code") { value("set_changed") }
            jsonPath("$.current.confirmed") { value(false) }
            jsonPath("$.updatedBy") { doesNotExist() }
            jsonPath("$.updatedAt") { doesNotExist() }
        }
    }

    @Test
    fun `an unknown field answers 400`() {
        patch("""{"weight":null,"effort":null,"confirmed":true,"foo":1}""").andExpect {
            status { isBadRequest() }
        }
    }

    @TestConfiguration
    class TestConfig {
        @Bean
        fun groupSessionQueryService(): GroupSessionQueryService = mockk()

        @Bean
        fun workoutService(): WorkoutService = mockk()

        @Bean
        fun workoutFieldPatchService(): WorkoutFieldPatchService = mockk()

        @Bean
        fun workoutFinishReadinessService(): WorkoutFinishReadinessService = mockk()

        @Bean
        fun workoutResponseAssembler(): WorkoutResponseAssembler = mockk()
    }
}

